"""Build only the five free Strength Lab calculators. No DB, identity or ranking changes."""
from pathlib import Path
import json,re,html
ROOT=Path(__file__).resolve().parent.parent;P=ROOT/'public'
copy=json.loads((ROOT/'content/lab/en.json').read_text());T=copy['text'];tools=copy['tools'];esc=lambda v:html.escape(str(v),quote=True)
# Reuse the built site shell without importing generators that rewrite other page families.
shell=(P/'tools/index.html').read_text();header=re.search(r'<a class="skip".*?</header>',shell,re.S).group();footer=re.search(r'<footer .*?</footer>',shell,re.S).group();header=header.replace('href="/tools/">Free tools','href="/strength-lab/">Strength Lab')
footer=footer.replace('<a href="/tools/" data-i18n="freeTools">Free tools</a>','<a href="/strength-lab/">Strength Lab</a><a href="/tools/" data-i18n="freeTools">All existing tools</a>')
locales={f.stem:json.loads(f.read_text()) for f in (ROOT/'content/lab').glob('*.json')}
(P/'lab-copy.js').write_text('// GENERATED from content/lab/*.json; add translations here, not in the math.\nexport const labLocales='+json.dumps(locales,ensure_ascii=False)+';\n')
def field(name,key,value,min=0,max=1000,step='any',hint='',cls=''):
 return f'<label class="lab-field {cls}"><span>{esc(T[key])}</span><div class="lab-input"><input id="lab-{name}" name="{name}" type="number" value="{value}" min="{min}" max="{max}" step="{step}" inputmode="decimal" required>{"<span data-lab-unit>kg</span>" if name in ["weight","maximum","target","bar","collars","reference","increment"] else ""}</div>{f"<small>{esc(hint)}</small>" if hint else ""}</label>'
def select(name,key,options,selected=''):
 return f'<label class="lab-field"><span>{esc(T[key])}</span><select id="lab-{name}" name="{name}">'+''.join(f'<option value="{esc(v)}"'+(' selected' if str(v)==str(selected) else '')+f'>{esc(l)}</option>' for v,l in options)+'</select></label>'
units=select('unit','unit',[('kg','Kilograms · kg'),('lb','Pounds · lb')],'kg')
stock=f'<fieldset class="lab-stock"><legend>{T["inventory"]}</legend><p>{T["stockHelp"]}</p><div class="lab-row-head"><span>{T["size"]}</span><span>{T["pairs"]}</span><span></span></div><div id="lab-inventory"></div><button type="button" id="lab-add-plate" class="lab-text-button">+ {T["addPlate"]}</button></fieldset>'
warm=f'<fieldset class="lab-stock"><legend>{T["warmRows"]}</legend><p>Percentages below refer to your working load, not your maximum. Keep the ramp gradual.</p><div class="warm-row-head"><span>{T["warmPercent"]}</span><span>{T["reps"]}</span><span>{T["rest"]}</span><span></span></div><div id="lab-warm-rows"></div><button type="button" id="lab-add-set" class="lab-text-button">+ {T["addSet"]}</button></fieldset>'
forms={
'one-rep-max':units+field('weight','weight',80,.001,2204.622622)+field('reps','reps',5,1,10,1,hint='1–10 whole reps. An estimate is not a max-testing instruction.'),
'percentages':units+select('kind','kind',[('estimated',T['estimated']),('tested',T['tested'])],'estimated')+field('maximum','maximum',100,.001,2204.622622)+field('increment','increment',0,0,100,'any',hint='0 = show calculated loads without rounding. Otherwise round down.')+f'<label class="lab-field lab-field-full"><span>{T["percentages"]}</span><input id="lab-percentages" name="percentages" value="50, 60, 70, 75, 80, 85, 90" required maxlength="160"><small>For example: 60, 72.5, 80. Presets are examples, not a prescription.</small></label>',
'plates':units+select('mode','mode',[('below',T['below']),('nearest',T['nearest'])],'below')+field('target','target',100,0,2204.622622)+field('bar','bar',20,0,220)+field('collars','collars',0,0,44,'any',hint='Enter both collars together; 0 if excluded.'),
'converter':select('unit','unit',[('kg','Kilograms → pounds'),('lb','Pounds → kilograms')],'kg')+field('amount','amount',80,0,10000),
'warm-up':units+select('basis','basis',[('working',T['working']),('estimated',T['fromEstimate'])],'working')+field('reference','reference',100,.001,2204.622622)+f'<div id="work-percent-field" hidden>'+field('workPercent','workPercent',75,40,90)+ '</div>'+field('bar','bar',20,0,220)+field('collars','collars',0,0,44)
}
def doc(title,body,tool=''):
 return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#090c13"><meta name="description" content="Free strength calculators: estimate 1RM, training percentages, smart plates, kg/lb conversion and adjustable warm-up sets. No account or ranking."><title>{esc(title)} | MONTE WO Strength Lab</title><link rel="icon" href="/assets/icon-32.png"><link rel="manifest" href="/manifest.json"><link rel="stylesheet" href="/fonts.css"><link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/launch.css"><link rel="stylesheet" href="/lab.css"><script src="/site.js" type="module"></script>'+('<script src="/lab.js" type="module"></script>' if tool else '')+f'</head><body class="lab-page" data-lab-tool="{tool}" data-lab-locale="en">{header}<main id="main">{body}</main>{footer}</body></html>'
def save(slug,body,title,tool=''):
 d=P/slug;d.mkdir(parents=True,exist_ok=True);(d/'index.html').write_text(doc(title,body,tool))
cards=''.join(f'<a class="lab-card" href="/strength-lab/{t["id"]}/"><div class="lab-card-top"><span>{t["symbol"]}</span><small>0{i+1} / FREE TOOL</small></div><h3>{esc(t["title"])}</h3><p>{esc(t["description"])}</p><div class="lab-card-bottom"><small>{esc(t["tag"])}</small><b>↗</b></div></a>' for i,t in enumerate(tools))
hub=f'''<section class="wrap lab-hero"><div><span class="eyebrow-pill"><span class="pulse"></span>MONTE WO / STRENGTH LAB</span><h1>Less guesswork.<br><em>More intention.</em></h1><p>{esc(copy['intro'])}</p><a class="button" href="/strength-lab/one-rep-max/">Start with your 1RM <span>↗</span></a><div class="lab-trust"><span>✓ Free to use</span><span>✓ On your device</span><span>✓ No account</span></div></div><div class="lab-hero-art" aria-label="Illustrative calculation: 80 kg for 5 reps gives an estimated 93.3 kg single"><div class="lab-orbit"></div><div class="lab-float lab-float-back"><span>PLATE CHECK / EACH SIDE</span><div class="lab-mini-bar"><i></i><i></i><b></b><i></i><i></i></div><p>2 × 20 kg <small>per side</small></p><small>100 kg total with a 20 kg bar</small></div><div class="lab-float lab-float-front"><div><span>ONE-REP MAX ESTIMATE</span><b>↗</b></div><strong>93.3 <small>kg</small></strong><div class="lab-sample-formula"><span>80 kg</span><i>×</i><span>5 reps</span></div><p>EPLEY FORMULA · ILLUSTRATIVE EXAMPLE</p></div><span class="lab-art-caption">PREPARATION, NOT A PRESCRIPTION.</span></div></section><section class="wrap lab-directory"><div class="lab-section-heading"><div><span class="eyebrow">FIVE TOOLS. ONE STRONGER START.</span><h2>Make the numbers work for you.</h2></div><span>01 — 05 / ALWAYS FREE</span></div><div class="lab-card-grid">{cards}<article class="lab-card lab-note-card"><span class="eyebrow">A NUMBER IS NOT A RANK.</span><h3>Useful calculations.<br>No automatic promotion.</h3><p>These tools do not award ranks, approve lifts or publish standards. MONTE WO ranking standards remain a separate, approval-gated project.</p><a href="/methodology/">Read the methodology status ↗</a></article></div><div class="lab-privacy"><span>⌁</span><p>{esc(T['privacy'])}</p></div></section><section class="wrap lab-bottom"><div><span class="eyebrow">MEASURE. PROVE. EARN. CLIMB.</span><h2>Prepare for the work.<br>Don’t chase the number.</h2><p>Use manageable loads, suitable equipment and sound technique. No calculator can assess your readiness, pain, form or recovery. If you need a personal plan, work with a qualified coach.</p></div><a class="text-link" href="/exercises/">Explore the exercise library ↗</a></section>'''
save('strength-lab',hub,'Free strength calculators')
for t in tools:
 id=t['id'];nav='<nav class="lab-sidebar" aria-label="Strength Lab tools"><a href="/strength-lab/">← '+T['allTools']+'</a>'+''.join(f'<a href="/strength-lab/{x["id"]}/"'+(' aria-current="page"' if x['id']==id else '')+f'><span>{x["symbol"]}</span>{esc(x["title"])}</a>' for x in tools)+'</nav>'
 body=f'''<section class="wrap lab-tool-hero"><a class="lab-back" href="/strength-lab/">MONTE WO / STRENGTH LAB</a><span class="eyebrow">{esc(t['tag'])}</span><h1>{esc(t['label'])}<span>.</span></h1><p>{esc(t['description'])}</p></section><section class="wrap lab-workspace">{nav}<div class="lab-main"><div class="lab-calculator"><form id="lab-form"><div class="lab-form-heading"><h2>Your inputs</h2><span>NO ACCOUNT REQUIRED</span></div><div class="lab-fields">{forms[id]}</div><p id="lab-unit-notice" class="lab-notice" role="status"></p>{stock if id in ['plates','warm-up'] else ''}{warm if id=='warm-up' else ''}<p class="lab-error" id="lab-error" role="alert"></p><div class="lab-actions"><button class="button" type="submit">{T['calculate']} ↗</button><button id="lab-reset" type="button">{T['reset']}</button></div><p class="lab-input-help">Estimates and planning examples—not instructions to attempt a maximum. Check the method and limitations below.</p></form><div class="lab-result" id="lab-result" role="region" aria-label="Calculation result" aria-live="polite"><h2>Calculate locally</h2><p>Enable JavaScript to use this tool. No account or upload is needed.</p></div></div><details class="lab-method" open><summary>{T['method']}</summary><p>{esc(t['method'])}</p><p>{esc(T['displayPrecision'])}</p><p>Software limits are input guardrails, not a declaration that a load is safe for you. Stop for pain; do not chase a number at the expense of technique.</p></details><div class="lab-privacy"><span>⌁</span><p>{esc(T['privacy'])}</p></div><p class="lab-rank-separation">Step 1 is a free calculator collection only. It cannot approve or publish a MONTE WO rank.</p></div></section>'''
 save('strength-lab/'+id,body,t['label'],id)
# One central offline route list, regenerated from this actual page catalog.
sw=P/'sw.js';s=sw.read_text();assets=['/strength-lab/','/lab.css','/lab.js','/lab-math.js','/lab-copy.js']+['/strength-lab/'+t['id']+'/' for t in tools]
if 'const LAB_ASSETS=' in s:s=re.sub(r'const LAB_ASSETS=.*?;', 'const LAB_ASSETS='+json.dumps(assets)+';',s)
else:s=s.replace('const ASSETS=[','const LAB_ASSETS='+json.dumps(assets)+';\nconst ASSETS=[...LAB_ASSETS,')
s=s.replace('montewo-core-v9-strength-index','montewo-core-v10-strength-lab');sw.write_text(s)
print('Built Strength Lab hub + five calculators. No ranking/auth/database changes.')
